-- Special pricing for JOB 2695 (Yale New Haven Hospital).
-- Generated from the DI (08.07.2023) and Homans (1.12.26) price books; matched to the price list by item code.
-- Run AFTER pricing.sql: Dashboard > SQL Editor > New query > paste this file > Run. Safe to re-run (updates prices).

begin;
  on conflict (id) do update set name = excluded.name, active = true, updated_at = now();
on conflict (book_id, item_key) do update set price = excluded.price, item_name = excluded.item_name, unit = excluded.unit, updated_at = now();
on conflict (book_id, item_key) do update set price = excluded.price, item_name = excluded.item_name, unit = excluded.unit, updated_at = now();
on conflict (book_id, item_key) do update set price = excluded.price, item_name = excluded.item_name, unit = excluded.unit, updated_at = now();
on conflict (book_id, item_key) do update set price = excluded.price, item_name = excluded.item_name, unit = excluded.unit, updated_at = now();
on conflict (book_id, item_key) do update set price = excluded.price, item_name = excluded.item_name, unit = excluded.unit, updated_at = now();
  on conflict (id) do update set name = excluded.name, active = true, updated_at = now();
on conflict (book_id, item_key) do update set price = excluded.price, item_name = excluded.item_name, unit = excluded.unit, updated_at = now();
on conflict (book_id, item_key) do update set price = excluded.price, item_name = excluded.item_name, unit = excluded.unit, updated_at = now();
on conflict (book_id, item_key) do update set price = excluded.price, item_name = excluded.item_name, unit = excluded.unit, updated_at = now();
commit;

-- Check: expect CT-DI about 1715 items and CT-Homans about 815 items.
select b.supplier, b.name, count(i.*) as items from public.price_books b left join public.price_book_items i on i.book_id = b.id where '2695' = any(b.job_keys) group by b.supplier, b.name;
